def reciprocal_rank_fusion(ranked_lists, k=60):
    # score each chunk by how highly it ranked across all lists
    scores = {}
    for ranked_list in ranked_lists:
        for rank, chunk in enumerate(ranked_list, start=1):
            scores[chunk] = scores.get(chunk, 0) + 1 / (k + rank)
    return sorted(scores.items(), key=lambda item: item[1], reverse=True)

# one ranked list per query variation
list_from_query_a = ["chunk_pricing", "chunk_refunds", "chunk_support"]
list_from_query_b = ["chunk_refunds", "chunk_pricing", "chunk_hours"]
list_from_query_c = ["chunk_pricing", "chunk_hours", "chunk_refunds"]

fused = reciprocal_rank_fusion([list_from_query_a, list_from_query_b, list_from_query_c])
print("Fused ranking:")
for chunk, score in fused:
    print(f"  {chunk}: {score:.4f}")
